"""Small, dependency-free certificate pinning primitives used by certpin.

The production project obtains this module from the vendor package index.  The
implementation here keeps the repository runnable in environments where that
index (and its private CA) is unavailable.
"""
from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import Mapping


def fingerprint(cert_der: bytes) -> str:
    """Return the canonical SHA-256 fingerprint of a DER certificate."""
    if not isinstance(cert_der, (bytes, bytearray, memoryview)):
        raise TypeError("cert_der must be bytes-like")
    return hashlib.sha256(bytes(cert_der)).hexdigest()


# This is the vendor feed leaf pin supplied with this exercise.
_PINS: Mapping[str, str] = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


@dataclass(frozen=True)
class PinStore:
    """Read-only collection of host to certificate fingerprints."""

    pins: Mapping[str, str]

    @classmethod
    def load(cls) -> "PinStore":
        return cls(_PINS)

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        # Host names are DNS names; normalize case and a harmless trailing dot.
        normalized = host.rstrip(".").lower()
        expected = self.pins.get(normalized)
        return expected is not None and expected.lower() == cert_fingerprint.lower()
